data.tool_json:
{
  "name": "lovense_controller",
  "description": "Controls connected Lovense toys via local HTTP API. ALWAYS call command='GetToys' first in a conversation to get exact toy IDs before calling 'Function' or 'Preset'.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "command": {
        "type": "string",
        "enum": ["GetToys", "Function", "Preset"],
        "description": "ALWAYS call 'GetToys' first before your very first 'Function' or 'Preset' call in a conversation. Only use 'Function' (motor control/stop) or 'Preset' (built-in patterns) after 'GetToys' has already returned a real toy ID in this chat."
      },
      "action": {
        "type": "string",
        "description": "For Function command only: comma-separated motor commands (e.g. 'Vibrate:10', 'Vibrate1:10', 'Vibrate:14,Fingering:12', 'Vibrate:16,Pump:2', or 'Stop'). Pass empty string '' for GetToys or Preset."
      },
      "name": {
        "type": "string",
        "enum": ["", "pulse", "wave", "fireworks", "earthquake"],
        "description": "For Preset command only: pattern name ('pulse', 'wave', 'fireworks', or 'earthquake'). Pass empty string '' for GetToys or Function."
      },
      "toy": {
        "type": "string",
        "description": "Pass '' for GetToys. For Function or Preset, you MUST copy the exact 12-character 'id' string returned by GetToys in this chat—NEVER make up or guess a hex ID."
      },
      "timeSec": {
        "type": "integer",
        "description": "Duration in seconds (1 to 99, e.g. 20). NEVER use 0 for Function or Preset—only use 0 for GetToys or Stop."
      },
      "apiVer": {
        "type": "integer",
        "description": "Always pass 1."
      }
    },
    "required": ["command", "action", "name", "toy", "timeSec", "apiVer"]
  }
}
